import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String args[])throws Exception
    {
        BufferedReader reader=new BufferedReader(new InputStreamReader(System.in));
        StringBuilder output=new StringBuilder();
        String[] inputLine=reader.readLine().split(" ");
        int totalNumbers=Integer.parseInt(inputLine[0]), maxBudget=Integer.parseInt(inputLine[1]);
        int index, balance=0;
        int[] numbers=new int[totalNumbers], prefixBalance=new int[totalNumbers];
        String[] numberStrings=reader.readLine().split(" ");
        for(index=0;index<totalNumbers;index++)
        {
            numbers[index]=Integer.parseInt(numberStrings[index]);
            if(numbers[index]%2==0) balance++;
            else balance--;
            prefixBalance[index]=balance;
        }
        ArrayList<Integer> differences=new ArrayList<>();
        for(index=0;index<totalNumbers-1;index++)
        {
            if(prefixBalance[index]==0) differences.add(Math.abs(numbers[index]-numbers[index+1]));
        }
        Collections.sort(differences);
        int totalCuts=0, currentSum=0;
        for(Integer diff:differences)
        {
            if(currentSum+diff<=maxBudget) {currentSum+=diff; totalCuts++;}
            if(currentSum>=maxBudget) break;
        }
        System.out.print(totalCuts);
    }
}
